from collections import deque

def process_jobs(job_ids, max_attempts=2):
    if max_attempts<1:
        raise ValueError('max_attempts must be positive')
    waiting=deque({'id':job_id,'attempts':0} for job_id in job_ids)
    completed=set()
    dead_letters=[]
    while waiting:
        job=waiting.popleft()
        if job['id'] in completed:
            continue
        try:
            if job['id']=='d-2':
                raise ValueError('unknown course')
            completed.add(job['id'])
        except ValueError as error:
            job['attempts']+=1
            if job['attempts']>=max_attempts:
                dead_letters.append({'id':job['id'],'reason':str(error)})
            else:
                waiting.append(job)
    return completed,dead_letters

